import {createCatalogReturn} from "/catalog-return.js";
import {createDiscovery} from "/discovery.js";
import {createJourney} from "/journey.js";
import {createMarketplace} from "/marketplace.js";
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₸';
const icons={search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',cart:'M3 3h2l3 12h10l3-9H6 M9 20h.01 M18 20h.01',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',arrow:'M4 12h16 M14 6l6 6-6 6',chevron:'M9 5l7 7-7 7',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',plus:'M12 5v14 M5 12h14',close:'M6 6l12 12 M6 18 18 6',check:'m5 12 4 4 10-10',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6L12 2Z m-5 10 3 3 6-6',truck:'M1 4h13v13H1z M14 9h5l4 5v3h-9 M8 19a2 2 0 1 1-4 0 2 2 0 0 1 4 0 M21 19a2 2 0 1 1-4 0 2 2 0 0 1 4 0',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z M20 2v4 M18 4h4',cpu:'M6 6h12v12H6z M9 9h6v6H9z M9 2v4 M15 2v4 M9 18v4 M15 18v4 M2 9h4 M2 15h4 M18 9h4 M18 15h4',box:'m12 2 10 5v10l-10 5-10-5V7l10-5Z M2 7l10 5 10-5 M12 12v10 M7 4.5l10 5',tool:'M14 6a5 5 0 0 0-6 6L2 18l4 4 6-6a5 5 0 0 0 6-6l-3 3-4-4 3-3Z',swap:'M3 7h17l-4-4 M21 17H4l4 4',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 22v-3a8 8 0 0 1 16 0v3',game:'M7 6h10a5 5 0 0 1 5 5v6a3 3 0 0 1-5 2l-2-2H9l-2 2a3 3 0 0 1-5-2v-6a5 5 0 0 1 5-5 M7 9v6 M4 12h6 M16 11h.01 M19 14h.01',monitor:'M2 3h20v14H2z M12 17v5 M7 22h10',ram:'M2 6h20v10H2z M5 9v4 M9 9v4 M13 9v4 M17 9v4 M5 16v3 M9 16v3 M13 16v3 M17 16v3',gpu:'M2 5h19v13H2z M2 18v3 M21 8h2 M21 15h2 M11 11a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M19 11a3 3 0 1 1-6 0 3 3 0 0 1 6 0',board:'M4 2h16v20H4z M7 5h6v6H7z M7 15h10 M7 18h10 M16 5v6',ssd:'M4 3h16v18H4z M8 7h8 M8 11h5 M8 17h.01 M16 17h.01',psu:'M3 4h18v16H3z M15 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0 M18 8h.01 M18 16h.01',case:'M5 2h14v20H5z M8 5h8 M8 8h8 M15 15a3 3 0 1 1-6 0 3 3 0 0 1 6 0',cooler:'M3 3h18v18H3z M12 10c-7-7-9 3-2 2 M14 12c7-7-3-9-2-2 M12 14c7 7 9-3 2-2 M10 12c-7 7 3 9 2 2',save:'M3 3h15l3 3v15H3z M7 3v6h10V3 M7 21v-8h10v8',logout:'M9 3H3v18h6 M8 12h13 M17 8l4 4-4 4',list:'M8 5h13 M8 12h13 M8 19h13 M3 5h.01 M3 12h.01 M3 19h.01',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 3',edit:'m16 3 5 5-12 12-6 1 1-6L16 3Z M13 6l5 5',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',filter:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',image:'M3 3h18v18H3z M3 17l6-6 4 4 3-3 5 5 M16 7h.01',chat:'M3 3h18v14H8l-5 4V3Z M7 8h10 M7 12h6',info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 11v6 M12 7h.01',refresh:'M20 8a8 8 0 0 0-14-3L3 8 M3 3v5h5 M4 16a8 8 0 0 0 14 3l3-3 M16 16h5v5'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[name]||icons.box}"/></svg>`;
const partIcons={cpu:'cpu',board:'board',ram:'ram',gpu:'gpu',ssd:'ssd',psu:'psu',case:'case',cooler:'cooler',monitor:'monitor',peripheral:'game',pc:'case'};
const state={products:[],categories:[],user:null,favorites:[],aiEnabled:false,filter:{category:'all',condition:'all',q:'',brand:[],min:'',max:'',sort:'popular'},homeTab:'all',builder:readLocal('component-build',{}),cart:readLocal('component-cart',[]),builderCategory:'cpu',builderCondition:'all',builderQ:'',evaluation:null,aiTask:'games',aiCondition:'mixed',aiBudget:450000,aiResult:null};
let renderSequence=0,toastTimer;
function readLocal(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return Array.isArray(fallback)?Array.isArray(v)?[...new Set(v.filter(Number.isInteger))]:fallback:v&&typeof v==='object'&&!Array.isArray(v)?v:fallback}catch{return fallback}}
function persist(){try{localStorage.setItem('component-build',JSON.stringify(state.builder));localStorage.setItem('component-cart',JSON.stringify(state.cart))}catch{}}
async function api(url,method='GET',data){const r=await fetch('/api'+url,{method,headers:method==='GET'?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const result=await r.json();if(!r.ok)throw Object.assign(new Error(result.error||'Ошибка запроса'),{status:r.status});return result}
async function bootstrap(){Object.assign(state,await api('/bootstrap'));state.cart=state.cart.filter(id=>state.products.some(p=>p.id===id));for(const [k,id]of Object.entries(state.builder))if(!state.products.some(p=>p.id===id&&p.category===k))delete state.builder[k];persist();renderHeader();renderFooter()}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
const find=id=>state.products.find(p=>p.id===Number(id));
const route=()=>location.hash.slice(1)||'home';
function go(name){if(route()===name)render();else location.hash=name}
const categoryName=id=>state.categories.find(c=>c.id===id)?.name||'Все товары';
const market=createMarketplace({state,esc,money,icon,api,find,go,render,bootstrap,toast,openModal,productImage,categoryName,modelOptions,sell,loginGate,getSpecLabels:()=>specLabels,clearDraft:form=>journey.clearDraft(form)});
const journey=createJourney({state,api,bootstrap,render,openModal,toast,money,esc,icon,authModal,checkoutForm,modelOptions});
const discovery=createDiscovery({state,esc,icon,money,market,card,categories,breadcrumb:(...args)=>breadcrumb(...args),demoNote:()=>demoNote(),go,toast});
const catalogReturn=createCatalogReturn({esc,icon,go});
const singular=id=>state.categories.find(c=>c.id===id)?.singular||id;
const brand=()=>`<a class="brand" href="#home" aria-label="Component.kz — главная"><img src="/assets/logo.svg" alt=""><span><strong>Component.kz</strong><small>Твой ПК начинается здесь</small></span></a>`;
function sprite(art,extra=''){
 let file='reference-home.jpg',x,y,w,h;
 if(art==='hero'){x=642;y=73;w=408;h=336}
 else if(art==='detail'){file='reference-product.jpg';x=168;y=154;w=440;h=285}
 else if(art==='amd'){x=220;y=650;w=84;h=98}
 else if(art?.startsWith('gpu')){file='reference-catalog.jpg';const n=Number(art.slice(3));x=247+(n%6)*208;y=n<6?359:642;w=174;h=87}
 else{const n=Number(art?.replace('cat',''))||0;x=[39,158,267,379,490,604,725,839,976,1118,1261][n]||39;y=437;w=n===9?108:85;h=76}
 return `<div class="sprite ${extra}" role="img" aria-label="Иллюстрация комплектующего" style="background-image:url('/assets/${file}');background-size:${1536/w*100}% ${1024/h*100}%;background-position:${x/(1536-w)*100}% ${y/(1024-h)*100}%"></div>`;
}
function productImage(p){return p.image?`<img src="${esc(p.image)}" alt="${esc(p.title)}" loading="lazy">`:p.demo?sprite(p.category==='cpu'&&p.brand==='AMD'?'amd':p.art):`<span class="photo-placeholder">${icon(partIcons[p.category])}<span>Без фотографии</span></span>`}
function renderHeader(){const r=route();$('#header').innerHTML=`<div class="topbar"><div class="container between"><span>Технологии ближе. Возможностей больше.</span><div class="top-links"><a href="#catalog">Маркетплейс Казахстана</a><a href="#help">Как это работает</a><span>RU</span></div></div></div><div class="container header-main">${brand()}<form class="search" id="search-form"><input name="q" aria-label="Поиск по товарам" placeholder="Поиск по товарам, брендам, моделям…" value="${esc(state.filter.q)}"><button type="submit" aria-label="Найти">${icon('search')}</button></form><div class="header-actions"><button class="location flex" data-action="city" aria-label="Выбрать город">${icon('pin')}<span class="city-label">${esc(state.city||'Казахстан')}</span></button><a class="icon-btn compare-shortcut" href="#compare" aria-label="Сравнение товаров">${icon('swap')}</a><a class="icon-btn" href="#favorites" aria-label="Избранное">${icon('heart')}${state.favorites.length?`<span class="count">${state.favorites.length}</span>`:''}</a><a class="icon-btn" href="#cart" aria-label="Корзина">${icon('cart')}${state.cart.length?`<span class="count">${state.cart.length}</span>`:''}</a><button class="user-btn" data-action="${state.user?'profile':'login'}"><span class="avatar">${state.user?esc(state.user.name.slice(0,2).toUpperCase()):icon('user')}</span><span>${state.user?'Мой профиль':'Войти'}</span></button></div></div><div class="nav-wrap"><nav class="container nav" aria-label="Основная навигация"><a class="catalog-button" href="#catalog">${icon('grid')} Каталог</a><a class="${r==='builder'?'active':''}" href="#builder">Собрать ПК</a><a class="${r==='ai'?'active':''}" href="#ai">${icon('spark')} AI-подбор <span class="pill">BETA</span></a><a href="#catalog?condition=used">Б/у комплектующие</a><a href="#catalog?category=pc">Готовые компьютеры</a><a class="sell-link" href="#sell">${icon('plus')} Разместить объявление</a></nav></div>`}
function renderFooter(){$('#footer').innerHTML=`<div class="footer"><div class="container between">${brand()}<div class="footer-links"><a href="#catalog">Каталог</a><a href="#builder">Конфигуратор</a><a href="#help">Как это работает</a></div><div class="footer-meta">© 2026 Component.kz<br>Собирай. Сравнивай. Находи своё.</div></div></div>`}
function referenceLabel(p){const model=find(p.spec?.referenceId);return !p.demo&&model?.demo&&model.category===p.category?`<small class="reference-model">Модель по справочнику: ${esc(model.title)}</small>`:''}
function card(p){return `<article class="product-card"><div class="product-top"><span class="pill ${p.condition==='used'?'green':'gray'}">${p.condition==='used'?'Б/у · предложение':'Новый'}</span><button class="favorite ${state.favorites.includes(p.id)?'on':''}" data-action="favorite" data-id="${p.id}" aria-label="${state.favorites.includes(p.id)?'Убрать из избранного':'Добавить в избранное'}" aria-pressed="${state.favorites.includes(p.id)}">${icon('heart')}</button></div><a href="#${p.status==='sold'&&market.own(p)?'edit':'product'}/${p.id}" class="product-picture" aria-label="${esc(p.title)}">${productImage(p)}</a><div class="product-info"><div class="meta"><span>${esc(p.city)}</span><span>${p.demo?'Демо':esc(p.seller||'Частное лицо')}</span></div><a href="#${p.status==='sold'&&market.own(p)?'edit':'product'}/${p.id}" class="product-title">${esc(p.title)}</a>${referenceLabel(p)}<div class="spec-chips">${Object.entries(p.spec).filter(([k,v])=>k!=='referenceId'&&typeof v!=='object').map(([,v])=>v).slice(0,2).map(v=>`<span>${esc(v)}</span>`).join('')}</div><div class="product-bottom"><div><div class="price">${money(p.price)}</div><div class="stock">${p.status==='sold'?'Снято с продажи':p.demo?'Демо-предложение':'Объявление активно'}</div></div>${market.own(p)?`<a class="icon-btn" href="#edit/${p.id}" aria-label="Редактировать объявление">${icon('edit')}</a>`:`<button class="icon-btn ${state.cart.includes(p.id)?'added':''}" data-action="cart-add" data-id="${p.id}" aria-label="${state.cart.includes(p.id)?'В корзине':'Добавить в корзину'}">${icon(state.cart.includes(p.id)?'check':'cart')}</button>`}</div>${p.status!=='sold'?market.compareButton(p):''}</div></article>`}
function categories(home=true){return `<div class="${home?'categories':'catalog-categories'}">${state.categories.map(c=>`<a class="category ${!home&&state.filter.category===c.id?'selected':''}" href="#catalog?category=${c.id}">${sprite('cat'+c.art)}<span>${c.name}</span></a>`).join('')}${home?`<a class="category used" href="#catalog?condition=used">${icon('swap')}<span>Б/у комплектующие</span></a>`:''}</div>`}
const empty=(title,text,href,button)=>`<div class="empty">${icon('box')}<h3>${title}</h3><p>${text}</p>${href?`<a class="btn primary" href="${href}">${button||'Перейти в каталог'} ${icon('arrow')}</a>`:''}</div>`;
const breadcrumb=items=>`<div class="breadcrumb"><a href="#home">Главная</a>${items.map(([t,h])=>`${icon('chevron')}${h?`<a href="${h}">${esc(t)}</a>`:`<span>${esc(t)}</span>`}`).join('')}</div>`;
const section=(title,subtitle='',link='#catalog',linkText='Смотреть все')=>`<div class="section-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${link?`<a class="link" href="${link}">${linkText} ${icon('arrow')}</a>`:''}</div>`;
const demoNote=()=>`<p class="demo-note">Демонстрационный каталог: цены и характеристики приведены для проверки MVP. Реальные объявления отмечены именем продавца.</p>`;
function home(){const list=state.products.filter(p=>state.homeTab==='all'||p.category===state.homeTab).slice(0,4);return `<div class="container page"><section class="hero"><div class="hero-copy"><div class="eyebrow">Больше, чем маркетплейс</div><h1>Собери свой<br><span>идеальный ПК</span></h1><p>Новые и б/у комплектующие, готовые сборки<br>и умный подбор под твои задачи.<br>Выбирай. Сравнивай. Собирай.</p><div class="hero-actions"><a class="btn primary" href="#catalog">Перейти в каталог ${icon('arrow')}</a><a class="btn dark" href="#builder">${icon('tool')} Собрать ПК</a></div></div><div class="hero-art">${sprite('hero')}<span class="hero-tag">Твой следующий уровень начинается здесь</span></div><div class="hero-features"><div class="hero-feature">${icon('spark')}<div><strong>Умный подбор конфигурации</strong><small>Твой бюджет. Твои задачи.<br>Твой идеальный компьютер.</small></div></div><div class="hero-feature">${icon('shield')}<div><strong>Всё о совместимости</strong><small>Проверяем основные параметры<br>комплектующих в сборке.</small></div></div><div class="hero-feature">${icon('swap')}<div><strong>Новые и б/у товары</strong><small>Больше возможностей —<br>меньше лишних расходов.</small></div></div></div></section>${categories()}<section>${section('Найди своё следующее обновление','Комплектующие, с которых начинается большее')}<div class="tabs">${[['all','Все товары'],['gpu','Видеокарты'],['cpu','Процессоры'],['board','Материнские платы'],['ram','Оперативная память'],['ssd','SSD']].map(([v,t])=>`<button class="tab ${state.homeTab===v?'active':''}" data-action="home-tab" data-value="${v}">${t}</button>`).join('')}</div><div class="home-products"><div class="products-grid">${list.map(card).join('')}</div><aside class="promo-builder"><div class="eyebrow">Конфигуратор ПК</div><h3>Твои задачи.<br>Твоя сборка.</h3><p>Игры, работа или творчество — собери компьютер под себя.</p>${sprite('cat10')}<a class="btn primary compact" href="#builder">Начать сборку ${icon('arrow')}</a><small>Новые и б/у детали в одной сборке</small></aside></div></section><div class="trust-row">${[['shield','Совместимость деталей','Проверяем ключевые параметры'],['spark','Оценка цены и мощности','Понятные расчёты, полезные выводы'],['swap','Новые и б/у','Выбирай то, что подходит тебе'],['pin','По всему Казахстану','Находи предложения в своём городе']].map(([i,t,s])=>`<div class="trust-item"><div class="trust-icon">${icon(i)}</div><div><strong>${t}</strong><small>${s}</small></div></div>`).join('')}</div><section>${section('Хорошему железу — вторую жизнь','Б/у комплектующие для разумного апгрейда','#catalog?condition=used','Все б/у предложения')}<div class="products-grid">${state.products.filter(p=>p.condition==='used').slice(0,4).map(card).join('')}</div></section><div class="promo-grid"><div class="promo"><h3>Твой апгрейд начинается<br>с продажи старого.</h3><p>Размести объявление и помоги своим комплектующим найти новый дом.</p><a class="btn compact" href="#sell">Разместить объявление ${icon('arrow')}</a>${icon('swap')}</div><div class="promo promo-dark"><h3>Не знаешь, что выбрать?</h3><p>Расскажи о своих задачах и бюджете.<br>Подберём совместимую конфигурацию.</p><a class="btn compact" href="#ai">Подобрать мой ПК ${icon('spark')}</a>${icon('cpu')}</div></div>${demoNote()}</div>`}
function catalog(){return discovery.page()}
function plural(n,a,b,c){return n%10===1&&n%100!==11?a:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?b:c}
const specLabels={socket:'Сокет',cores:'Ядра',threads:'Потоки',watts:'Потребление, Вт',memory:'Объём видеопамяти',type:'Тип',length:'Длина, мм',ram:'Тип памяти',form:'Форм-фактор',size:'Объём, GB',speed:'Частота, МГц',power:'Мощность, Вт',certificate:'Сертификат',gpuMax:'Длина видеокарты до, мм',coolerMax:'Высота кулера до, мм',sockets:'Совместимые сокеты',tdp:'Отвод тепла до, Вт',height:'Высота, мм',hz:'Частота, Гц',resolution:'Разрешение',cpu:'Процессор',gpu:'Видеокарта',ssd:'Накопитель'};
function detail(id){const p=find(id);if(!p)return `<div class="container page">${empty('Объявление недоступно','Возможно, продавец уже снял товар с продажи.','#catalog')}</div>`;return `<div class="container page">${breadcrumb([['Каталог','#catalog'],[categoryName(p.category),'#catalog?category='+p.category],[p.title]])}<div class="detail-grid"><div><div class="detail-photo">${p.id===1?sprite('detail'):productImage(p)}<span class="photo-note">${p.demo?'Иллюстрация из дизайн-референса':p.image?'Фото продавца':'Продавец пока не добавил фото'}</span></div><div class="trust-row" style="grid-template-columns:1fr 1fr;padding:17px 0;margin:0;border:0"><div class="trust-item"><div class="trust-icon">${icon('box')}</div><div><strong>${p.condition==='new'?'Новый товар':'Б/у товар'}</strong><small>Состояние указано продавцом</small></div></div><div class="trust-item"><div class="trust-icon">${icon('pin')}</div><div><strong>${esc(p.city)}</strong><small>Город объявления</small></div></div></div></div><div><div class="flex"><span class="pill ${p.condition==='used'?'green':'gray'}">${p.condition==='used'?'Б/у':'Новый'}</span>${p.demo?'<span class="pill">Демо-предложение</span>':''}</div><h1 class="detail-title">${esc(p.title)}</h1><p class="detail-subtitle">${esc(p.brand)} &nbsp; · &nbsp; Код объявления: ${p.id}</p>${referenceLabel(p)}<table class="spec-table"><tbody>${Object.entries(p.spec).filter(([k])=>k!=='referenceId').map(([k,v])=>`<tr><td>${esc(specLabels[k]||k)}</td><td>${esc(Array.isArray(v)?v.join(', '):v)}</td></tr>`).join('')||'<tr><td>Характеристики</td><td>Уточните у продавца</td></tr>'}</tbody></table>${(p.demo||p.spec.referenceId)&&p.category!=='pc'?`<button class="btn soft" style="margin-top:17px" data-action="build-add" data-id="${p.id}">${icon('plus')} Добавить в сборку</button>`:''}</div><aside class="panel buy-panel"><div class="between"><strong class="price">${money(p.price)}</strong></div>${market.own(p)?`<a class="btn primary wide" href="#edit/${p.id}">${icon('edit')} Редактировать объявление</a>`:`<button class="btn primary wide" data-action="cart-add" data-id="${p.id}">${icon('cart')} ${state.cart.includes(p.id)?'В корзине':'Добавить в корзину'}</button><button class="btn soft wide" data-action="buy-now" data-id="${p.id}">Оставить заявку</button>`}${market.compareButton(p)}<button class="btn wide" data-action="favorite" data-id="${p.id}">${icon('heart')} ${state.favorites.includes(p.id)?'В избранном':'В избранное'}</button><div class="delivery"><div>${icon('user')}<div><strong>${p.demo?'Демонстрационный продавец':esc(p.seller||'Частное лицо')}</strong><small>${p.demo?'Для знакомства с сервисом':'Автор объявления'}</small></div></div><div>${icon('chat')}<div><strong>Договоритесь с продавцом</strong><small>Контакт передаётся в заявке</small></div></div><div>${icon('shield')}<div><strong>Проверьте перед покупкой</strong><small>Тесты, состояние, комплектацию</small></div></div></div></aside></div><div class="detail-bottom"><section class="panel"><h3>О товаре</h3><div class="description">${esc(p.description)}</div></section><section class="ai-panel"><div class="ai-heading">${icon('spark')}<h3>Оценка мощности и цены</h3><span class="pill">BETA</span></div>${p.score?`<div class="flex"><div class="score-ring" style="--score:${p.score/10}"><div><strong>${p.score}</strong><small>из 100</small></div></div><div><strong>Ориентировочный индекс</strong><p>${p.score>=75?'Для требовательных задач':p.score>=55?'Для игр и повседневной работы':'Для базового игрового компьютера'}.</p></div></div><p class="ai-fineprint">Демонстрационный коэффициент модели, не результат бенчмарка. Производительность зависит от всей конфигурации.</p>`:'<p>Для этого товара ещё нет проверенных данных производительности. Посмотри оценку полной сборки в конфигураторе.</p>'}<a class="link" href="#ai">Оценить полную конфигурацию ${icon('arrow')}</a></section></div>${section('Похожие предложения','',`#catalog?category=${p.category}`)}<div class="products-grid">${state.products.filter(a=>a.category===p.category&&a.id!==p.id).slice(0,4).map(card).join('')}</div></div>`}
function selectedParts(){return Object.values(state.builder).map(find).filter(Boolean)}
function evaluationPanel(e){if(!e)return `<div class="ai-panel"><div class="ai-heading">${icon('spark')}<h3>Твоя сборка в цифрах</h3></div><div class="build-empty-card">${icon('cpu')}Добавь процессор и видеокарту — здесь появится оценка мощности и цены.</div><a class="btn soft wide" href="#ai">Подобрать автоматически</a></div>`;return `<div class="ai-panel"><div class="ai-heading">${icon('spark')}<h3>Оценка сборки</h3><span class="pill">BETA</span></div><div class="ai-result-title">${icon(e.errors.length?'info':e.complete?'shield':'cpu')}<span>${e.errors.length?'Есть несовместимые детали':e.complete?'Основные параметры совместимы':'Хорошее начало!'}</span></div><p>${e.complete?'Конфигурация подобрана. Проверь детали перед покупкой.':`Осталось добавить: ${e.missing.map(singular).join(', ')}.`}</p>${e.value?`<div class="score-box"><div class="score-ring" style="--score:${e.value}"><div><strong>${e.value}</strong><small>из 10</small></div></div><div class="score-copy"><strong>Цена / мощность<br>${e.value>=8?'Выгодно':e.value>=6?'Сбалансированно':'Есть куда улучшить'}</strong><small>Расчёт по выбранным деталям</small></div></div>`:''}${e.tasks?`<strong class="small">Для чего подходит</strong>${[['games','Игры'],['work','Работа и учёба'],['render','Монтаж и 3D']].map(([k,t])=>`<div class="metric"><div class="between"><span>${t}</span><strong>${e.tasks[k]} / 100</strong></div><div class="bar"><span style="width:${e.tasks[k]}%"></span></div></div>`).join('')}`:''}${e.errors.map(w=>`<div class="warning error">${esc(w)}</div>`).join('')}${e.warnings.slice(0,e.complete?2:1).map(w=>`<div class="warning">${esc(w)}</div>`).join('')}<p class="ai-fineprint">Ориентировочная модель расчёта, не бенчмарк. FPS и актуальные рыночные цены не подтверждены. Рекомендуемый БП: от ${e.recommendedPower} Вт.</p><button class="btn soft wide compact" data-action="ai-explain">${icon('spark')} ${state.aiEnabled?'Объяснить с AI':'Подробнее о расчёте'}</button></div>`}
function builder(){const parts=selectedParts(),total=parts.reduce((s,p)=>s+p.price,0),cat=state.builderCategory;const list=state.products.filter(p=>(p.demo||p.spec.referenceId)&&p.category===cat&&(state.builderCondition==='all'||p.condition===state.builderCondition)&&p.title.toLowerCase().includes(state.builderQ.toLowerCase()));return `<div class="container page"><div class="builder-title"><div><h1 class="page-heading">Собери ПК <span class="blue">под свои задачи</span></h1><p class="page-subtitle">Новые или б/у комплектующие. Одна сборка. Всё под твоим контролем.</p></div><div class="builder-features"><span class="builder-feature">${icon('shield')} Проверка совместимости</span><span class="builder-feature">${icon('swap')} Новые и б/у детали</span></div></div><div class="builder-grid"><nav class="part-nav" aria-label="Компоненты сборки">${state.categories.filter(c=>c.id!=='pc').sort((a,b)=>['cpu','board','ram','gpu','ssd','psu','case','cooler','monitor','peripheral'].indexOf(a.id)-['cpu','board','ram','gpu','ssd','psu','case','cooler','monitor','peripheral'].indexOf(b.id)).map(c=>`<button class="part-button ${cat===c.id?'active':''}" data-action="builder-category" data-value="${c.id}">${icon(partIcons[c.id])}<span><strong>${c.singular}</strong><small class="${state.builder[c.id]?'part-done':''}">${state.builder[c.id]?'✓ Выбрано':c.id==='monitor'||c.id==='peripheral'?'Необязательно':'Выбрать'}</small></span></button>`).join('')}</nav><section class="builder-list"><div class="builder-list-head"><h3>Выбери: ${singular(cat).toLowerCase()}</h3><form id="builder-search" class="search" style="margin-bottom:14px"><input name="q" placeholder="Поиск в категории…" aria-label="Поиск комплектующих" value="${esc(state.builderQ)}"><button aria-label="Найти">${icon('search')}</button></form><div class="tabs">${[['all','Все'],['new','Новые'],['used','Б/у']].map(([v,t])=>`<button class="tab ${state.builderCondition===v?'active':''}" data-action="builder-condition" data-value="${v}">${t}</button>`).join('')}</div></div>${list.map(p=>`<article class="part-product">${productImage(p)}<div class="part-product-text"><strong>${esc(p.title)}</strong><small>${Object.values(p.spec).slice(0,3).map(v=>esc(Array.isArray(v)?v.join(' / '):v)).join(' · ')}<br>${p.condition==='used'?'Б/у':'Новый'} · ${p.demo?'Демо':esc(p.seller||'Продавец')}</small><div class="price">${money(p.price)}</div></div><button class="icon-btn ${state.builder[cat]===p.id?'selected':''}" data-action="build-add" data-id="${p.id}" aria-label="Выбрать ${esc(p.title)}">${icon(state.builder[cat]===p.id?'check':'plus')}</button></article>`).join('')||empty('Нет вариантов','Измени состояние товара или поисковый запрос.')}</section><aside class="panel build-summary"><div class="between"><h3>Твоя сборка <span class="muted small">${parts.length}</span></h3><button class="reset" data-action="build-reset">Сбросить</button></div>${parts.length?parts.map(p=>`<div class="selected-part">${productImage(p)}<div><small>${singular(p.category)}</small><strong>${esc(p.title)}</strong><div class="price">${money(p.price)} <span class="muted small">${p.condition==='used'?'б/у':''}</span></div></div><button data-action="build-remove" data-value="${p.category}" aria-label="Удалить ${esc(p.title)}">${icon('close')}</button></div>`).join(''):'<div class="summary-empty">Твой будущий ПК пока ждёт детали.<br>Начни с процессора или воспользуйся подбором.</div>'}<div class="build-total between"><span>Итого</span><strong class="price">${money(total)}</strong></div><div class="build-actions"><button class="btn primary wide" data-action="assembly" ${!state.evaluation?.complete||!state.evaluation?.compatible?'disabled':''}>${icon('tool')} Заказать сборку</button><button class="btn wide" data-action="build-save" ${!parts.length?'disabled':''}>${icon('save')} Сохранить сборку</button></div><p class="ai-fineprint">Стоимость сборки и доставки согласовывается отдельно. Заявка не списывает деньги.</p></aside>${evaluationPanel(state.evaluation)}</div><div class="promo-grid"><div class="promo promo-dark"><h3>Начни с того, что тебе нужно.</h3><p>Игры, монтаж или работа — подберём комплектующие под твой бюджет.</p><a class="btn compact" href="#ai">Запустить подбор ${icon('arrow')}</a>${icon('spark')}</div><div class="promo"><h3>Б/у — тоже хороший выбор.</h3><p>Комбинируй новые и б/у детали. Проверяй состояние, тесты и комплектацию.</p><a class="btn compact" href="#catalog?condition=used">Посмотреть предложения ${icon('arrow')}</a>${icon('swap')}</div></div>${demoNote()}</div>`}
function aiPage(){const r=state.aiResult;return `<div class="container page"><div class="ai-page"><div class="ai-intro"><div class="ai-orb">${icon('spark')}</div><div class="eyebrow blue" style="margin-bottom:12px">Меньше сомнений. Больше возможностей.</div><h1 class="page-heading">Твой идеальный ПК. <span class="blue">Без головной боли.</span></h1><p class="page-subtitle">Расскажи, для чего тебе компьютер. Остальное подберём вместе.</p></div><div class="ai-form-grid"><form id="ai-form" class="panel stack"><h3 style="margin:0">Что важно для тебя?</h3><label class="field">Для каких задач?</label><div class="choice-row">${[['games','game','Игры'],['work','monitor','Работа и учёба'],['render','cpu','Монтаж и 3D']].map(([v,i,t])=>`<button type="button" class="choice ${state.aiTask===v?'active':''}" data-action="ai-task" data-value="${v}">${icon(i)}${t}</button>`).join('')}</div><div><label class="field" for="budget">Твой бюджет</label><div class="budget-output" id="budget-output">${money(state.aiBudget)}</div><div class="budget-entry"><input class="input" id="budget" name="budget" type="number" required min="100000" max="10000000" step="1" value="${state.aiBudget}" aria-describedby="budget-hint"><span>₸</span></div><input id="budget-range" type="range" aria-label="Изменить бюджет ползунком" min="100000" max="${Math.max(1500000,state.aiBudget)}" step="1000" value="${state.aiBudget}"><p class="small muted" id="budget-hint">Введи точную сумму от 100 000 до 10 000 000 ₸.</p></div><label class="field">Какие комплектующие?</label><div class="choice-row">${[['new','Только новые'],['mixed','Новые + б/у'],['used','Только б/у']].map(([v,t])=>`<button type="button" class="choice ${state.aiCondition===v?'active':''}" data-action="ai-condition" data-value="${v}">${t}</button>`).join('')}</div><p class="form-error"></p><button class="btn primary wide" type="submit">${icon('spark')} Подобрать конфигурацию</button><p class="ai-fineprint">Подбор по бюджету и правилам совместимости из демонстрационного каталога. ${state.aiEnabled?'AI может объяснить результат.':'AI-объяснения не подключены; алгоритмический подбор работает.'}</p></form><div class="panel ai-output">${r?`${icon('shield')}<span class="pill green" style="align-self:flex-start;margin-bottom:14px">Основные параметры совместимы</span><h3>Твоя сборка готова.</h3><div class="price" style="font-size:29px">${money(r.evaluation.total)}</div><p>В пределах бюджета. Остаток: ${money(state.aiBudget-r.evaluation.total)}.</p><div class="stack" style="gap:9px;margin-bottom:20px">${r.parts.map(p=>`<div class="between small"><span>${esc(p.title)}</span><span class="muted nowrap">${p.condition==='used'?'Б/у':'Новый'}</span></div>`).join('')}</div><button class="btn primary" data-action="apply-recommendation">Открыть в конфигураторе ${icon('arrow')}</button>`:`${icon('cpu')}<h3>Хорошая сборка —<br>это больше, чем мощность.</h3><p>Важны совместимость, разумная цена и именно те возможности, которыми ты будешь пользоваться.</p><ul><li>Процессор и плата с одинаковым сокетом</li><li>Подходящие память, корпус и охлаждение</li><li>Запас мощности блока питания</li><li>Полная конфигурация в пределах бюджета</li></ul><div class="info">${icon('info')} Подбор — отправная точка. Перед покупкой уточни BIOS, состояние и наличие у продавца.</div>`}</div></div><div class="panel" style="margin-top:24px"><div class="between"><div><h3 style="margin-bottom:8px">Уже выбрал компьютер?</h3><p class="small muted" style="margin:0">Добавь его детали в конфигуратор и сравни мощность с ценой продавца.</p></div><a class="btn soft" href="#builder">Оценить сборку ${icon('arrow')}</a></div></div></div></div>`}
function loginGate(title='Твой личный кабинет',text='Войди, чтобы управлять объявлениями, сохранять сборки и отправлять заявки.'){return `<div class="container page"><div class="auth-message">${empty(title,text)}<button class="btn primary wide" data-action="login" style="margin-top:15px">Войти или зарегистрироваться ${icon('arrow')}</button></div></div>`}
function favorites(){if(!state.user)return loginGate('Сохрани то, что понравилось','Войди, чтобы твоё избранное было доступно с любого устройства.');const list=state.products.filter(p=>state.favorites.includes(p.id));return `<div class="container page">${breadcrumb([['Избранное']])}<h1 class="page-heading">Избранное</h1><p class="page-subtitle">Всё, что приглянулось, в одном месте.</p><div class="products-grid">${list.length?list.map(card).join(''):empty('Здесь будет твоё избранное','Нажми на сердечко в карточке товара, чтобы сохранить предложение.','#catalog')}</div></div>`}
async function profile(){if(!state.user)return loginGate();const p=await api('/profile');return `<div class="container page"><div class="profile-grid"><aside class="panel profile-nav"><a class="active" href="#profile">${icon('user')} Мой профиль</a><a href="#profile" data-scroll="my-listings">${icon('list')} Мои объявления</a><a href="#profile" data-scroll="my-orders">${icon('box')} Мои заявки</a><a href="#favorites">${icon('heart')} Избранное</a><a href="#profile" data-scroll="my-builds">${icon('cpu')} Мои сборки</a><a href="#ai">${icon('spark')} AI-подбор</a><button data-action="logout">${icon('logout')} Выйти</button></aside><section><h1 class="page-heading">Мой профиль</h1><p class="page-subtitle">Твои объявления, заявки и будущие сборки.</p><div class="panel profile-card"><div class="avatar">${esc(p.user.name.slice(0,2).toUpperCase())}</div><div><h2>${esc(p.user.name)}</h2><p>${esc(p.user.email)}<br>${esc(p.user.city)} · Частное лицо</p></div><button class="btn compact" data-action="edit-profile">${icon('edit')} Редактировать</button></div><div class="profile-stats">${[[p.listings.filter(l=>l.status==='active').length,'Активных объявлений'],[p.orders.length,'Заявок на покупку'],[p.builds.length,'Сохранённых сборок']].map(([n,t])=>`<div class="panel stat"><span>${t}</span><strong>${n}</strong></div>`).join('')}</div><section class="profile-section" id="my-listings">${section('Мои объявления','','#sell','Разместить объявление')}<div class="products-grid">${p.listings.length?p.listings.map(l=>`<div>${card(l)}<div class="listing-state between"><span class="pill ${l.status==='active'?'green':'gray'}">${l.status==='active'?'Активно':'Снято с продажи'}</span><button class="link small" data-action="listing-status" data-id="${l.id}" data-value="${l.status==='active'?'sold':'active'}">${l.status==='active'?'Снять с продажи':'Вернуть в продажу'}</button></div></div>`).join(''):empty('Первое объявление — первый шаг','Расскажи о своём компьютере или комплектующих.','#sell','Разместить объявление')}</div></section><section class="profile-section" id="my-orders">${section('Мои заявки','',null)}<div class="panel">${p.orders.length?p.orders.map(orderRow).join(''):'<p class="small muted">Ты ещё не отправлял заявки. Найди подходящее предложение в каталоге.</p>'}</div></section>${p.inquiries.length?`<section class="profile-section">${section('Входящие заявки','Покупатели заинтересовались твоими объявлениями',null)}<div class="panel">${p.inquiries.map(market.incomingRow).join('')}</div></section>`:''}<section class="profile-section" id="my-builds">${section('Мои сборки','','#builder','Создать сборку')}${p.builds.length?p.builds.map(b=>`<div class="saved-build"><div><strong>${esc(b.name)}</strong><small>${b.parts.length} комплектующих · ${new Date(b.created+'Z').toLocaleDateString('ru-RU')}</small></div><div class="flex"><button class="btn soft compact" data-action="load-build" data-ids="${b.parts.join(',')}">Открыть ${icon('arrow')}</button><button class="icon-btn" data-action="delete-build" data-id="${b.id}" aria-label="Удалить сборку">${icon('trash')}</button></div></div>`).join(''):empty('У твоих идей будет своё место','Сохрани конфигурацию и вернись к ней, когда захочешь.','#builder','Создать сборку')}</section></section></div></div>`}
function orderRow(o){return `<div class="order-row"><div><strong>Заявка №${o.id} · ${o.kind==='assembly'?'Сборка ПК':'Покупка'}</strong><small>${o.items.map(p=>esc(p.title)).join(', ')}</small><small>${new Date(o.created+'Z').toLocaleDateString('ru-RU')} · ${esc(o.city)}${o.items.some(p=>p.demo)?' · Демо-заявка':''}</small></div><span class="price nowrap">${money(o.total)}</span>${market.orderActions(o)}</div>`}
function modelOptions(category){return '<option value="">Другая модель / укажу в описании</option>'+state.products.filter(p=>p.demo&&p.category===category).filter((p,i,a)=>a.findIndex(x=>x.title===p.title)===i).map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}
function sell(){if(!state.user)return loginGate('Продай железо. Освободи место новому.','Создай аккаунт, чтобы опубликовать объявление и получать заявки покупателей.');return `<div class="container page">${breadcrumb([['Новое объявление']])}<h1 class="page-heading">Дай своему железу новую жизнь</h1><p class="page-subtitle">Пара минут — и твоё предложение уже в каталоге.</p><div class="sell-layout"><form id="sell-form" class="panel stack"><h3 class="form-section-title"><span>1</span> Что продаёшь?</h3><label class="field">Название объявления<input name="title" required minlength="5" maxlength="120" placeholder="Например, MSI GeForce RTX 4060 Ti 8GB"></label><div class="fields-2"><label class="field">Категория<select name="category" id="listing-category">${state.categories.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></label><label class="field">Состояние<select name="condition"><option value="used">Б/у</option><option value="new">Новое</option></select></label></div><label class="field">Модель из справочника (необязательно)<select name="modelId" id="listing-model">${modelOptions("gpu")}</select><span class="small muted">Выбери точную модель, чтобы товар участвовал в подборе и оценке. Характеристики модели будут добавлены автоматически.</span></label><label class="field">Бренд<input name="brand" maxlength="60" placeholder="MSI, ASUS, AMD…"></label><label class="field">Описание<textarea name="description" required minlength="20" maxlength="3000" placeholder="Укажи характеристики, срок использования, состояние, комплектацию и результаты тестов."></textarea></label><h3 class="form-section-title"><span>2</span> Фотография</h3><label class="upload">${icon('image')}Добавь настоящее фото товара<input name="image" type="file" accept="image/jpeg,image/png,image/webp"><span class="small">JPEG, PNG или WebP · до 1,5 МБ</span></label>${market.photoControl()}<h3 class="form-section-title"><span>3</span> Цена и город</h3><div class="fields-2"><label class="field">Цена, ₸<input name="price" type="number" required min="100" max="100000000" placeholder="150 000"></label><label class="field">Город<select name="city">${['Астана','Алматы','Шымкент','Караганда','Актобе','Кызылорда'].map(c=>`<option ${c===state.user.city?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="info">Покупатели смогут отправить заявку. Контакты появятся в твоём профиле, в разделе «Входящие заявки».</div><p class="form-error"></p><button class="btn primary wide" type="submit">Опубликовать в локальном каталоге ${icon('arrow')}</button></form><aside class="panel sell-tips"><h3>${icon('spark')} Хорошее объявление<br>говорит само за себя</h3><p>Сфотографируй товар при хорошем освещении. Покажи разъёмы, маркировку и внешнее состояние.</p><p>Укажи точную модель. Для видеокарты пригодятся температуры и результаты стресс-теста.</p><p>Расскажи о ремонте, оставшейся гарантии и причине продажи. Честность помогает найти своего покупателя.</p><div class="warning">Не отправляй товар до согласования условий сделки. Оплата и доставка пока оформляются напрямую с покупателем.</div></aside></div></div>`}
function cart(){const items=state.cart.map(find).filter(Boolean);return `<div class="container page">${breadcrumb([['Корзина']])}<h1 class="page-heading">Твои находки</h1><p class="page-subtitle">${items.length?`${items.length} ${plural(items.length,'товар','товара','товаров')} в корзине`:'Самое интересное ещё впереди.'}</p>${items.length?`<div class="cart-layout"><div class="panel">${items.map(p=>`<article class="cart-row">${productImage(p)}<div><a href="#product/${p.id}"><h3>${esc(p.title)}</h3></a><small>${p.condition==='used'?'Б/у':'Новый'} · ${esc(p.city)} ${p.demo?'· Демо':''}</small></div><span class="price">${money(p.price)}</span><button class="icon-btn" data-action="cart-remove" data-id="${p.id}" aria-label="Убрать из корзины">${icon('trash')}</button></article>`).join('')}</div><aside class="panel"><h3>Сводка</h3><div class="between small muted"><span>Товары</span><span>${items.length}</span></div><div class="build-total between"><strong>Итого</strong><strong class="price">${money(items.reduce((s,p)=>s+p.price,0))}</strong></div><button class="btn primary wide" data-action="checkout">Оставить заявку ${icon('arrow')}</button><p class="ai-fineprint">Без онлайн-оплаты. Продавец получает твои контактные данные вместе с заявкой.</p>${items.some(p=>p.demo)?'<div class="info">В корзине есть демо-товары. По ним будет сохранена учебная заявка без реального продавца.</div>':''}</aside></div>`:empty('Здесь пока пусто','Сохрани понравившиеся предложения в корзине, чтобы вернуться к ним позже.','#catalog','Найти своё обновление')}</div>`}
function help(){return `<div class="container page"><div class="ai-page">${breadcrumb([['Как это работает']])}<h1 class="page-heading">Знакомься, Component.kz</h1><p class="page-subtitle">Место для тех, кто собирает, обновляет и любит компьютеры.</p><div class="ai-form-grid"><div class="panel stack"><h3>Покупай и продавай</h3><p class="description">Найди комплектующие или готовый компьютер в каталоге. Фильтруй по состоянию, бренду, цене и городу. Создай аккаунт, добавь объявление с фотографией или оставь продавцу заявку с контактом.</p><a class="btn primary" href="#catalog">Открыть каталог ${icon('arrow')}</a></div><div class="panel stack"><h3>Собирай под себя</h3><p class="description">Выбирай новые или б/у детали. Конфигуратор проверяет сокет, память, мощность питания и основные размеры. Автоподбор ищет полную совместимую конфигурацию в пределах бюджета.</p><a class="btn primary" href="#builder">Собрать компьютер ${icon('arrow')}</a></div></div><div class="panel" style="margin-top:22px"><h3>Оценка мощности и цены</h3><p class="description">В MVP используется прозрачная расчётная модель: условные коэффициенты CPU/GPU и фактическая сумма выбранных объявлений. Индекс мощности = 75% от меньшего из GPU и CPU × 1,2 + 25% CPU. Оценка цены/мощности = индекс / цена × 42 000, с ограничением от 1 до 10. Это не бенчмарк, не измеренный FPS и не актуальная рыночная оценка.

При подключённом AI-сервисе можно получить текстовое объяснение сборки. Модель не заменяет проверку характеристик, BIOS и состояния б/у деталей.</p><h3>Что уже работает</h3><p class="description">Регистрация, вход, объявления с фотографией, избранное, сохранённые сборки и заявки хранятся на сервере в базе данных. Для заявок на реальные объявления продавец видит контакты в профиле. Демо-заявки сохраняются для проверки сценария. Заявки на сборку ждут обработки оператором сервиса.</p><div class="info">Это локальный MVP. Онлайн-оплата, доставка, модерация, подтверждение продавцов и внешние уведомления пока не подключены. Начальные товары — демонстрационные примеры.</div></div></div></div>`}
async function render(){const seq=++renderSequence;const r=route(),[page,query]=r.split('?');if(page==='catalog')market.readFilters(query);
 renderHeader();document.title=({home:'Твой ПК начинается здесь',catalog:'Каталог комплектующих',builder:'Собери свой ПК',ai:'Умный подбор',profile:'Мой профиль',sell:'Новое объявление',cart:'Корзина',favorites:'Избранное',compare:'Сравнение товаров',help:'Как это работает'}[page]||'Объявление')+' — Component.kz';
 try{let content;if(page==='builder'){state.evaluation=selectedParts().length?await api('/evaluate','POST',{ids:selectedParts().map(p=>p.id)}):null;content=builder()}else if(page==='profile'){content=await profile()}else if(page.startsWith('edit/')){content=await market.editor(page.split('/')[1])}else if(page==='compare'){content=market.comparePage()}else content=page==='home'?home():page==='catalog'?catalog():page.startsWith('product/')?detail(page.split('/')[1]):page==='ai'?aiPage():page==='sell'?sell():page==='cart'?cart():page==='favorites'?favorites():page==='help'?help():`<div class="container page">${empty('Страница не найдена','Вернись на главную или открой каталог.','#home','На главную')}</div>`;if(seq===renderSequence){$('#main').innerHTML=content;market.afterRender();journey.afterRender();discovery.afterRender();catalogReturn.afterRender()}}catch(e){if(seq===renderSequence)$('#main').innerHTML=`<div class="container page">${empty('Не удалось загрузить страницу',esc(e.message))}<button class="btn primary" data-action="retry" style="margin-top:15px">Попробовать ещё раз</button></div>`}}
function openModal(title,subtitle,content){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div><p class="modal-sub">${subtitle}</p>${content}`;if(!d.open)d.showModal()}
function authModal(register=false){openModal(register?'Начни с хорошего знакомства':'С возвращением!',register?'Создай аккаунт, чтобы собирать, покупать и продавать.':'Твои сборки и находки уже ждут тебя.',`<form id="auth-form" class="stack" data-register="${register}">${register?'<label class="field">Как тебя зовут?<input name="name" autocomplete="name" required minlength="2" maxlength="60" placeholder="Твоё имя"></label>':''}<label class="field">Email<input type="email" name="email" autocomplete="email" required maxlength="120" placeholder="you@example.com"></label><label class="field">Пароль<input type="password" name="password" autocomplete="${register?'new-password':'current-password'}" required minlength="${register?8:1}" maxlength="128" placeholder="${register?'Не меньше 8 символов':'Твой пароль'}"></label><p class="form-error"></p><button class="btn primary wide">${register?'Создать аккаунт':'Войти'} ${icon('arrow')}</button></form><p class="modal-switch">${register?'Уже есть аккаунт?':'Ещё нет аккаунта?'} <button data-action="${register?'login':'register'}">${register?'Войти':'Зарегистрироваться'}</button></p>`)}
function requireUser(){if(state.user)return true;authModal();return false}
function checkout(kind,ids){return journey.checkout(kind,ids)}
function checkoutForm(kind,ids){if(!requireUser())return;const items=ids.map(find).filter(Boolean);if(!items.length)return toast('Сначала выбери товары.');state.orderDraft={kind,ids};openModal(kind==='assembly'?'Заявка на сборку':'Заявка на покупку',`${items.length} ${plural(items.length,'позиция','позиции','позиций')} · ${money(items.reduce((s,p)=>s+p.price,0))}. Без списания денег.`,`<form id="checkout-form" class="stack"><label class="field">Имя<input name="name" required minlength="2" maxlength="60" value="${esc(state.user.name)}"></label><label class="field">Телефон<input name="phone" type="tel" required minlength="10" maxlength="25" placeholder="+7 700 123 45 67" autocomplete="tel"></label><label class="field">Город<input name="city" required minlength="2" maxlength="60" value="${esc(state.user.city)}"></label><label class="field">Комментарий<textarea name="note" maxlength="1000" placeholder="Удобное время, вопросы по товару или пожелания к сборке"></textarea></label>${items.some(p=>p.demo)?'<div class="info">В заявке есть демонстрационные товары. Реальная покупка по ним не совершается.</div>':''}<label class="check"><input type="checkbox" required>Согласен передать контактные данные продавцу или сборщику</label><p class="form-error"></p><button class="btn primary wide">Сохранить заявку ${icon('arrow')}</button></form>`)}
document.addEventListener('click',async e=>{
 const scroll=e.target.closest('[data-scroll]');if(scroll&&route()==='profile'){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return}
 const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=Number(b.dataset.id),v=b.dataset.value;
 try{
 if(catalogReturn.action(action))return;
 if(await discovery.action(action,b))return;
 if(await journey.action(action,b))return;
 if(await market.action(action,b))return;
 if(action==='login')return authModal();if(action==='register')return authModal(true);if(action==='close-modal')return $('#modal').close();if(action==='profile')return go('profile');
 if(action==='retry'){await bootstrap();return render()}
 if(action==='logout'){await api('/auth/logout','POST',{});await bootstrap();go('home');return toast('Ты вышел из аккаунта.')}
 if(action==='home-tab'){state.homeTab=v;return render()}
 if(action==='favorite'){if(!requireUser())return;const active=!state.favorites.includes(id);await api('/favorites','POST',{id,active});state.favorites=active?[...state.favorites,id]:state.favorites.filter(n=>n!==id);renderHeader();document.querySelectorAll(`.favorite[data-id="${id}"]`).forEach(el=>{el.classList.toggle('on',active);el.setAttribute('aria-pressed',active);el.setAttribute('aria-label',active?'Убрать из избранного':'Добавить в избранное')});if(route()==='favorites'||route().startsWith('product/'))await render();return toast(active?'Добавлено в избранное':'Удалено из избранного')}
 if(action==='cart-add'){if(!state.cart.includes(id)){state.cart.push(id);persist();renderHeader();b.classList.add('added');if(b.classList.contains('icon-btn'))b.innerHTML=icon('check');else b.innerHTML=icon('cart')+' В корзине';toast('Товар добавлен в корзину')}else go('cart');return}
 if(action==='cart-remove'){state.cart=state.cart.filter(n=>n!==id);persist();return render()}
 if(action==='buy-now')return checkout('purchase',[id]);if(action==='checkout')return checkout('purchase',state.cart);if(action==='assembly')return checkout('assembly',selectedParts().map(p=>p.id));
 if(action==='builder-category'){state.builderCategory=v;state.builderQ='';return render()}
 if(action==='builder-condition'){state.builderCondition=v;return render()}
 if(action==='build-add'){const p=find(id);if(!p)return;state.builder[p.category]=id;persist();if(route()==='builder')await render();else toast('Добавлено в сборку. Открой «Собрать ПК».');return}
 if(action==='build-remove'){delete state.builder[v];persist();return render()}
 if(action==='build-reset'){state.builder={};persist();return render()}
 if(action==='build-save'){if(!requireUser())return;return openModal('Сохрани свою идею','Сборка останется в профиле, и ты сможешь продолжить позже.',`<form id="save-build-form" class="stack"><label class="field">Название сборки<input name="name" required minlength="2" maxlength="80" value="Мой новый ПК"></label><p class="form-error"></p><button class="btn primary wide">${icon('save')} Сохранить сборку</button></form>`)}
 if(action==='load-build'){state.builder={};for(const id of b.dataset.ids.split(',').map(Number)){const p=find(id);if(p)state.builder[p.category]=id}persist();return go('builder')}
 if(action==='delete-build'){await api('/builds/'+id,'DELETE',{});toast('Сборка удалена');return render()}
 if(action==='filters-toggle')return $('#filters').classList.toggle('open');
 if(action==='reset-filters'){state.filter={category:'all',condition:'all',q:'',brand:[],min:'',max:'',sort:'popular'};state.city='';return go('catalog')}
 if(action==='ai-task'){state.aiTask=v;state.aiResult=null;return render()}
 if(action==='ai-condition'){state.aiCondition=v;state.aiResult=null;return render()}
 if(action==='apply-recommendation'){if(!state.aiResult)return;state.builder=Object.fromEntries(state.aiResult.parts.map(p=>[p.category,p.id]));persist();go('builder');return}
 if(action==='ai-explain'){if(!requireUser())return;openModal(state.aiEnabled?'AI-объяснение':'Как мы оцениваем сборку','Ориентировочная оценка по выбранной конфигурации.','<div class="loading" style="padding:35px">Готовим объяснение…</div>');const r=await api('/ai/explain','POST',{ids:selectedParts().map(p=>p.id)});if(!$('#modal').open)return;return openModal(r.source==='openai'?'AI-объяснение':'Расчётная оценка','Основано на параметрах выбранных деталей.',`<div class="ai-explanation">${esc(r.text)}</div><div class="info">${esc(r.evaluation.method)}</div><form id="price-evaluation-form" class="stack"><label class="field">Цена продавца за такой ПК, ₸<input type="number" name="price" required min="100" max="100000000" value="${r.evaluation.total}"></label><p class="form-error"></p><button class="btn primary">Сравнить цену и мощность</button></form><div id="price-evaluation-result"></div>`)}
 if(action==='listing-status'){await api('/listings/'+id,'PATCH',{status:v});await bootstrap();toast(v==='sold'?'Объявление снято с продажи':'Объявление снова активно');return render()}
 if(action==='edit-profile')return openModal('Редактировать профиль','Как тебя увидят покупатели.',`<form id="profile-form" class="stack"><label class="field">Имя<input name="name" required minlength="2" maxlength="60" value="${esc(state.user.name)}"></label><label class="field">Город<input name="city" required minlength="2" maxlength="60" value="${esc(state.user.city)}"></label><p class="form-error"></p><button class="btn primary">Сохранить изменения</button></form>`);
 if(action==='city')return openModal('Твой город','Покажем предложения поближе к тебе.',`<form id="city-form" class="stack"><label class="field">Город<select name="city"><option value="">Весь Казахстан</option>${['Астана','Алматы','Шымкент','Караганда','Актобе','Кызылорда'].map(c=>`<option ${state.city===c?'selected':''}>${c}</option>`).join('')}</select></label><button class="btn primary">Показать предложения</button></form>`);
 }catch(error){toast(error.message)}
});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const f=Object.fromEntries(new FormData(form)),submit=form.querySelector('button[type="submit"],button:not([type])'),error=form.querySelector('.form-error');if(error)error.textContent='';if(submit)submit.disabled=true;
 try{
 if(discovery.submit(form,f))return;
 if(await market.submit(form,f))return;
 if(form.id==='search-form'){state.filter.q=f.q.trim();state.filter.category='all';state.filter.brand=[];return go('catalog?q='+encodeURIComponent(f.q.trim()))}
 if(form.id==='price-filter'){if(f.min&&f.max&&Number(f.min)>Number(f.max))throw new Error('Минимальная цена не может быть больше максимальной.');state.filter.min=f.min;state.filter.max=f.max;return market.syncFilters()}
 if(form.id==='builder-search'){state.builderQ=f.q.trim();return render()}
 if(form.id==='auth-form'){const register=form.dataset.register==='true';await api('/auth/'+(register?'register':'login'),'POST',f);const continuation=journey.takePending();$('#modal').close();await bootstrap();await render();await journey.resume(continuation);return toast(register?'Аккаунт создан. Добро пожаловать!':'Ты вошёл в аккаунт')}
 if(form.id==='profile-form'){await api('/profile','PATCH',f);$('#modal').close();await bootstrap();await render();return toast('Профиль обновлён')}
 if(form.id==='city-form'){state.city=f.city;$('#modal').close();return market.syncFilters()}
 if(form.id==='save-build-form'){await api('/builds','POST',{name:f.name,ids:selectedParts().map(p=>p.id)});$('#modal').close();return toast('Сборка сохранена в профиле')}
 if(form.id==='checkout-form'){const result=await api('/orders','POST',{...f,...state.orderDraft});if(state.orderDraft.kind==='purchase'){state.cart=state.cart.filter(id=>!state.orderDraft.ids.includes(id));persist()}openModal('Заявка сохранена',`Номер заявки: ${result.id}`,`<div class="success">${icon('check')} ${result.demo?'Демо-заявка сохранена в базе. Реальная покупка не совершается.':state.orderDraft.kind==='assembly'?'Заявка на сборку сохранена и ждёт обработки оператором.':'Продавец увидит заявку и твои контакты в личном кабинете.'}</div><p class="small muted">Статус и состав заявки доступны в твоём профиле. Деньги не списывались.</p><a class="btn primary wide" href="#profile" data-action="close-modal">Мои заявки ${icon('arrow')}</a>`);renderHeader();await render();return}
 if(form.id==='ai-form'){state.aiBudget=Number(f.budget);state.aiResult=await api('/recommend','POST',{budget:state.aiBudget,condition:state.aiCondition,task:state.aiTask});return render()}
 if(form.id==='price-evaluation-form'){const r=await api('/evaluate','POST',{ids:selectedParts().map(p=>p.id),price:Number(f.price)});$('#price-evaluation-result').innerHTML=`<div class="${Number(f.price)>r.total?'warning':'success'}">Цена/мощность: <strong>${r.value??'—'} / 10</strong>.<br>По сравнению с суммой деталей (${money(r.total)}): ${Number(f.price)>=r.total?'+':'−'}${money(Math.abs(Number(f.price)-r.total))}. Сравнение с выбранными объявлениями, не со всем рынком.</div>`;return}
 if(form.id==='sell-form'){const file=f.image;delete f.image;if(file?.size){if(file.size>1500000)throw new Error('Фото должно быть не больше 1,5 МБ.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Выбери JPEG, PNG или WebP.');f.image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Не удалось прочитать фото.'));reader.readAsDataURL(file)})}const r=await api('/listings','POST',f);journey.clearDraft(form);await bootstrap();go('product/'+r.id);return toast('Объявление опубликовано в локальном каталоге')}
 }catch(err){journey.checkoutError(form,err);if(error)error.textContent=err.message;else toast(err.message)}finally{if(submit)submit.disabled=false}
});
document.addEventListener('change',e=>{const el=e.target;if(discovery.change(el))return;market.change(el);if(el.id==='listing-category')$('#listing-model').innerHTML=modelOptions(el.value);if(el.dataset.filter){if(el.dataset.filter==='city')state.city=el.value;else state.filter[el.dataset.filter]=el.value;market.syncFilters()}if(el.dataset.brand){const brand=el.dataset.brand;state.filter.brand=el.checked?[...state.filter.brand,brand]:state.filter.brand.filter(v=>v!==brand);market.syncFilters()}});
document.addEventListener('input',e=>{if(['budget','budget-range'].includes(e.target.id)){state.aiBudget=Number(e.target.value);if(e.target.id==='budget-range')$('#budget').value=state.aiBudget;else{$('#budget-range').max=Math.max(1500000,state.aiBudget);$('#budget-range').value=state.aiBudget}$('#budget-output').textContent=money(state.aiBudget);if(state.aiResult){state.aiResult=null;$('.ai-output').innerHTML='<h3>Бюджет изменился</h3><p>Нажми «Подобрать конфигурацию», чтобы обновить результат.</p>'}}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('#modal').close()}});
window.addEventListener('hashchange',()=>{window.scrollTo(0,0);render()});
try{await bootstrap();await render()}catch(e){$('#main').innerHTML=`<div class="container page">${empty('Сервер пока недоступен','Запусти проект командой npm start и обнови страницу.')}<button class="btn primary" data-action="retry">Повторить подключение</button></div>`}
